package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_nullValue_TriageGen1Test {

    private StringWriter writer;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws Exception {
        writer = new StringWriter();
        jsonWriter = new JsonWriter(writer);
    }

    @Test
    public void testNullValue_WithDeferredNameAndSerializeNullsTrue() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.name("test");
        ArgumentCaptor<String> nameCaptor = ArgumentCaptor.forClass(String.class);
        verify(jsonWriter).writeDeferredName(nameCaptor.capture());
        assertTrue(nameCaptor.getValue().equals("test"));
        jsonWriter.nullValue();
        assertEquals("null", writer.toString());
    }

    @Test
    public void testNullValue_WithDeferredNameAndSerializeNullsFalse() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.name("test");
        jsonWriter.nullValue();
        assertEquals("", writer.toString());
    }

    @Test
    public void testNullValue_WithoutDeferredName() throws IOException {
        jsonWriter.nullValue();
        assertEquals("null", writer.toString());
    }

    @Test
    public void testNullValue_WithNullWriter() throws IOException {
        StringWriter nullWriter = null;
        JsonWriter nullJsonWriter = new JsonWriter(nullWriter);
        nullJsonWriter.nullValue();
        // Since writer is null, no output is expected
        assertEquals("", nullWriter.toString());
    }

    @Test(expected = IOException.class)
    public void testNullValue_ThrowsIOException() throws IOException {
        JsonWriter mockJsonWriter = mock(JsonWriter.class);
        doThrow(new IOException()).when(mockJsonWriter).beforeValue(false);
        mockJsonWriter.nullValue();
    }
}
